import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Mode, Preview } from '../types'

const previews = atom({ plugin: 'paste-preview', key: 'previews' } as const, [] as Preview[])
const mode = atom({ plugin: 'paste-preview', key: 'mode' } as const, 'auto' as Mode)
const isHd = atom({ plugin: 'paste-preview', key: 'isHd' } as const, false)

/** 一張縮圖的上限（欄 x 列）；一次最多並排幾張 */
const MAX_COLS = 32
const MAX_ROWS = 10
const MAX_SHOWN = 3

/** 支援終端機圖像協定（kitty graphics + Unicode placeholder）的 TERM_PROGRAM */
const HD_TERMINALS = ['ghostty', 'kitty']

const IMAGE_TOKEN = /\[Image #\d+\]/g

const imageTokens = (text: string) => text.match(IMAGE_TOKEN) ?? []

/** 輪詢輸入框的間隔 */
const POLL_MS = 400

/** 32bpp BMP（NSBitmapImageRep 產出，BI_BITFIELDS）轉成 Raster 的半格字元 cells */
export const bmpToCells = (bmp: Uint8Array): { cells: string; columns: number; rows: number } => {
  const view = new DataView(bmp.buffer, bmp.byteOffset, bmp.byteLength)
  const offset = view.getUint32(10, true)
  const width = view.getInt32(18, true)
  const rawHeight = view.getInt32(22, true)
  const bpp = view.getUint16(28, true)
  const height = Math.abs(rawHeight)
  const isTopDown = rawHeight < 0
  const masks =
    view.getUint32(30, true) === 3
      ? [54, 58, 62, 66].map(at => view.getUint32(at, true))
      : [0x00ff0000, 0x0000ff00, 0x000000ff, bpp === 32 ? 0xff000000 : 0]
  const shifts = masks.map(m => (m === 0 ? 0 : 31 - Math.clz32(m & -m)))
  const stride = Math.ceil((width * bpp) / 32) * 4
  const bytes = bpp / 8

  const pixel = (x: number, y: number): number => {
    const row = isTopDown ? y : height - 1 - y
    const at = offset + row * stride + x * bytes
    let word = 0
    for (let k = bytes - 1; k >= 0; k--) word = (word * 256 + view.getUint8(at + k)) >>> 0
    const channel = (i: number) => {
      const m = masks[i] ?? 0
      return m === 0 ? 255 : ((word & m) >>> 0) >>> (shifts[i] ?? 0)
    }
    // 透明像素交給終端機預設底色
    return channel(3) < 128 ? 0x01000000 : (channel(0) << 16) | (channel(1) << 8) | channel(2)
  }

  const rows = Math.ceil(height / 2)
  const words = new Uint32Array(width * rows * 3)
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < width; x++) {
      const top = pixel(x, y * 2)
      const bottom = y * 2 + 1 < height ? pixel(x, y * 2 + 1) : 0x01000000
      const i = (y * width + x) * 3
      // ▀：前景畫上半像素、背景畫下半像素
      words[i] = 0x2580
      words[i + 1] = top
      words[i + 2] = bottom
    }
  }

  return { cells: new Uint8Array(words.buffer).toBase64(), columns: width, rows }
}

const capture = async ($: EngineInterface) => {
  const list = await read($, previews)
  const path = `${$.plugin.root}/.cache/paste-${Date.now()}.png`
  const { exitCode, stdout, stderr } = await $.process.run(
    ['osascript', '-l', 'JavaScript', `${$.plugin.root}/bin/clip.js`, path, String(MAX_COLS), String(MAX_ROWS)],
    { timeoutMs: 10_000 },
  )
  if (exitCode !== 0) {
    $.ui.toast(`paste-preview: 讀不到剪貼簿（${stderr.trim().slice(0, 80)}）`)
    return
  }
  const out = JSON.parse(stdout)
  if (out.error) {
    $.ui.toast('paste-preview: 剪貼簿裡沒有圖片')
    return
  }
  const raster = bmpToCells(Uint8Array.fromBase64(out.bmp))
  const preview: Preview = { path, width: Number(out.width), height: Number(out.height), ...raster }
  await update($, previews, () => [...list, preview].slice(-MAX_SHOWN))
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'paste-preview',
      description: 'Preview pasted images: now | open | clear | hd | text | auto | off',
      argumentHint: '[now|open|clear|hd|text|auto|off]',
    })
    const { stdout } = await $.process.run(['/usr/bin/printenv', 'TERM_PROGRAM'])
    const { exitCode: kitty } = await $.process.run(['/usr/bin/printenv', 'KITTY_WINDOW_ID'])
    const term = stdout.trim().toLowerCase()
    await update($, isHd, () => kitty === 0 || HD_TERMINALS.some(name => term.includes(name)))
    // 清掉一天前的暫存原圖
    await $.process
      .run(['/usr/bin/find', `${$.plugin.root}/.cache`, '-name', 'paste-*.png', '-mtime', '+1', '-delete'])
      .catch(() => undefined)

    // 貼圖時引擎直接把 [Image #N] 放進輸入框、不觸發 prompt.edit，所以輪詢輸入框
    let seen = new Set(imageTokens((await $.prompt.read()).text))
    let isBusy = false
    $.clock.every(POLL_MS, () => {
      if (isBusy) return
      isBusy = true
      void (async () => {
        const tokens = imageTokens((await $.prompt.read()).text)
        const isNew = tokens.some(t => !seen.has(t))
        seen = new Set(tokens)
        if (isNew && (await read($, mode)) !== 'off') {
          await capture($)
        } else if (tokens.length === 0 && (await read($, previews)).length > 0) {
          // 圖片標記都被刪掉了，收起預覽
          await update($, previews, () => [])
        }
      })()
        .catch(error => $.ui.toast(`paste-preview: ${String(error).slice(0, 100)}`))
        .finally(() => {
          isBusy = false
        })
    })

    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    // 清除失敗不能擋住送出
    void update($, previews, () => []).catch(() => undefined)

    return next(e)
  })

  on('command.run', { command: 'paste-preview' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    const list = await read($, previews)
    if (arg === '' || arg === 'now') {
      await capture($)
      return { text: '已擷取剪貼簿圖片。' }
    }
    if (arg === 'open') {
      if (list.length === 0) return { text: '目前沒有預覽中的圖片。' }
      await $.process.run(['open', ...list.map(p => p.path)])
      return { text: `已用預設看圖程式開啟 ${list.length} 張。` }
    }
    if (arg === 'clear') {
      await update($, previews, () => [])
      return { text: '預覽已清除。' }
    }
    if (arg === 'hd' || arg === 'text' || arg === 'auto' || arg === 'off') {
      await update($, mode, () => arg)
      return { text: `顯示模式：${arg}` }
    }
    return { text: '用法：/paste-preview [now|open|clear|hd|text|auto|off]' }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const list = await read($, previews)
    const current = await read($, mode)
    if (e.surface !== 'terminal' || e.props.hasSurvey || list.length === 0 || current === 'off') {
      return next(e)
    }
    const useHd = current === 'hd' || (current === 'auto' && (await read($, isHd)))
    const { Box, Button, Image, Raster, Text } = $.ui.resolve(e)
    // 由最新一張往回塞，塞到區塊寬度為止
    const shown: Preview[] = []
    let width = 0
    for (const p of [...list].reverse()) {
      width += p.columns + (shown.length > 0 ? 2 : 0)
      if (width > e.props.bodyColumns && shown.length > 0) break
      shown.unshift(p)
    }
    const hidden = list.length - shown.length

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={2}>
          {shown.map((p, i) => (
            <Box key={p.path} flexDirection="column">
              {useHd ? (
                <Image
                  key={`img-${i}`}
                  source={{ file: p.path, format: 'png' }}
                  columns={p.columns}
                  rows={p.rows}
                  alt={`[圖片 ${p.width}x${p.height}]`}
                />
              ) : (
                <Raster key={`img-${i}`} cells={p.cells} columns={p.columns} rows={p.rows} />
              )}
              <Text dimColor>
                {p.width}x{p.height}
              </Text>
            </Box>
          ))}
        </Box>
        <Box flexDirection="row" gap={1}>
          <Button
            key="open"
            label="開原圖"
            onPress={() => $.process.run(['open', ...list.map(p => p.path)])}
          />
          <Button key="hide" label="收起" onPress={() => update($, previews, () => [])} />
          {hidden > 0 && <Text dimColor>另有 {hidden} 張放不下</Text>}
        </Box>
      </Box>
    )
  })
}

