export type Preview = {
  /** 原圖 PNG 的絕對路徑 */
  path: string
  /** 原圖像素尺寸 */
  width: number
  height: number
  /** 半格字元縮圖：Raster 的 cells、欄數、列數 */
  cells: string
  columns: number
  rows: number
}

/** auto：依 TERM_PROGRAM 判斷；hd：終端機圖像協定；text：半格字元；off：關閉 */
export type Mode = 'auto' | 'hd' | 'text' | 'off'

declare module 'claude-code' {
  interface PluginState {
    'paste-preview': { previews: Preview[]; mode: Mode; isHd: boolean }
  }
}
